import { Component, OnInit } from '@angular/core';
import { ApiService } from '../../services/api.service';

@Component({
  selector: 'app-home',
  template: `
    <div class="home-container">
      <header class="flex justify-between items-center mb-8">
        <h1>Incidentes Recentes</h1>
        <button *ngIf="isLoggedIn" routerLink="/report" class="btn btn-primary">Relatar Novo</button>
      </header>

      <div class="incidents-grid" *ngIf="incidents.length > 0; else noIncidents">
        <div *ngFor="let incident of incidents" class="glass-card incident-card animate-fade-in">
          <div class="severity-badge" [ngClass]="'severity-' + incident.severity_level.toLowerCase()">
            {{ incident.severity_level }}
          </div>
          <h3>{{ incident.description | slice:0:100 }}{{ incident.description.length > 100 ? '...' : '' }}</h3>
          <p class="incident-meta">
            <span>📅 {{ incident.datetime | date:'short' }}</span>
            <span>📍 {{ incident.location.latitude }}, {{ incident.location.longitude }}</span>
          </p>
          <p class="user-meta">Relatado por: {{ incident.user }}</p>
        </div>
      </div>

      <ng-template #noIncidents>
        <div class="glass-card p-8 text-center">
          <p>Nenhum incidente relatado recentemente. A comunidade está segura!</p>
        </div>
      </ng-template>
    </div>
  `,
  styles: [`
    .incidents-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
      gap: 1.5rem;
    }
    .incident-card {
      padding: 1.5rem;
      position: relative;
      overflow: hidden;
    }
    .severity-badge {
      position: absolute;
      top: 1rem;
      right: 1rem;
      padding: 0.25rem 0.75rem;
      border-radius: 1rem;
      font-size: 0.75rem;
      font-weight: 700;
      text-transform: uppercase;
      background: rgba(0,0,0,0.2);
    }
    .incident-meta {
      margin-top: 1rem;
      font-size: 0.875rem;
      color: var(--text-muted);
      display: flex;
      flex-direction: column;
      gap: 0.25rem;
    }
    .user-meta {
      margin-top: 1rem;
      font-size: 0.75rem;
      font-weight: 600;
      color: var(--primary);
    }
  `]
})
export class HomeComponent implements OnInit {
  incidents: any[] = [];
  isLoggedIn = false;

  constructor(private api: ApiService) {}

  ngOnInit() {
    this.isLoggedIn = !!localStorage.getItem('token');
    this.api.getIncidents().subscribe(data => {
      this.incidents = data;
    });
  }
}
